#include <string.h>

void str_reverse(char *s) {
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; i++) {
        char t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
}

seed_examples.tests:
#include <assert.h>
#include <string.h>
int main(void) {
    char a[] = "hello";
    str_reverse(a);
    assert(strcmp(a, "olleh") == 0);
    char b[] = "";
    str_reverse(b);
    assert(b[0] == '\0');
    return 0;
}

