#include <limits.h>

long parse_int(const char *s, int *ok) {
    int neg = 0;
    unsigned long v = 0, lim;
    *ok = 0;
    if (*s == '+' || *s == '-') neg = *s++ == '-';
    if (!*s) return 0;
    lim = neg ? (unsigned long)LONG_MAX + 1 : (unsigned long)LONG_MAX;
    for (; *s; s++) {
        if (*s < '0' || *s > '9') return 0;
        unsigned d = (unsigned)(*s - '0');
        if (v > (lim - d) / 10) return 0;
        v = v * 10 + d;
    }
    *ok = 1;
    if (neg) return v == (unsigned long)LONG_MAX + 1 ? LONG_MIN : -(long)v;
    return (long)v;
}

seed_examples.tests:
#include <assert.h>
#include <limits.h>
int main(void) {
    int ok;
    assert(parse_int("42", &ok) == 42 && ok);
    assert(parse_int("-17", &ok) == -17 && ok);
    parse_int("", &ok); assert(!ok);
    parse_int("12a", &ok); assert(!ok);
    parse_int("99999999999999999999", &ok); assert(!ok);
    assert(parse_int("-9223372036854775808", &ok) == LONG_MIN && ok);
    return 0;
}

